async def act(page):
    import re
    import asyncio

    # Target article full title and a robust distinguishing substring
    full_title = "Beijing extends Mars mission lead; stranded astronauts back home: China’s year in space"
    target_substr = "Beijing extends Mars"

    # 1) Try to close any obvious popup by clicking a close-like button (defensive)
    try:
        # Look for buttons that appear to be close controls by accessible name
        close_btns = page.get_by_role("button", name=re.compile(r"\bclose\b|[×✕✖]|^x$", re.IGNORECASE))
        if await close_btns.count() > 0:
            await close_btns.first.click()
            await asyncio.sleep(0.3)
    except Exception:
        # If popup close fails, continue; search may still work
        pass

    # 2) Use the complementary region's searchbox (hierarchical selector) to search for the full title
    try:
        comp = page.get_by_role("complementary")
        if await comp.count() > 0:
            comp = comp.first
            # Prefer a searchbox named "Search"
            sb_loc = comp.get_by_role("searchbox", name="Search")
            if await sb_loc.count() == 0:
                # fallback to any textbox inside complementary
                tb_loc = comp.get_by_role("textbox")
                if await tb_loc.count() > 0:
                    searchbox = tb_loc.first
                else:
                    searchbox = None
            else:
                searchbox = sb_loc.first

            if searchbox is not None:
                try:
                    await searchbox.fill(full_title)
                    # Submit with Enter to avoid clicking a possibly obscured button
                    await searchbox.press("Enter")
                    # Give the main region a moment to update
                    try:
                        await page.get_by_role("main").wait_for(timeout=3000)
                    except Exception:
                        await asyncio.sleep(1)
                except Exception:
                    # If search fill/submit fails, we'll fall back to scanning links below
                    pass
    except Exception:
        pass

    # 3) Attempt to find a link to the target article inside the main region
    match_href = None
    try:
        main = page.get_by_role("main")
        if await main.count() > 0:
            # First try a direct link whose visible name contains the target substring
            try:
                link_candidates = main.get_by_role("link", name=re.compile(re.escape(target_substr), re.IGNORECASE))
                if await link_candidates.count() > 0:
                    # pick first candidate and get its href
                    cand = link_candidates.first
                    try:
                        match_href = await cand.get_attribute("href") or ""
                    except Exception:
                        match_href = ""
            except Exception:
                # ignore
                pass

            # Fallback: iterate article entries and inspect heading->link or first link
            if not match_href:
                articles = main.get_by_role("article")
                a_count = await articles.count()
                for i in range(a_count):
                    art = articles.nth(i)
                    # Prefer heading->link pattern
                    try:
                        if await art.get_by_role("heading").count() > 0:
                            heading = art.get_by_role("heading").first
                            if await heading.get_by_role("link").count() > 0:
                                link = heading.get_by_role("link").first
                                try:
                                    t = (await link.inner_text()).strip()
                                except Exception:
                                    t = ""
                                try:
                                    h = await link.get_attribute("href") or ""
                                except Exception:
                                    h = ""
                                if (t and target_substr.lower() in t.lower()) or (full_title.lower() in t.lower()):
                                    match_href = h
                                    break
                        # Fallback: first link inside the article
                        if await art.get_by_role("link").count() > 0 and not match_href:
                            link = art.get_by_role("link").first
                            try:
                                t = (await link.inner_text()).strip()
                            except Exception:
                                t = ""
                            try:
                                h = await link.get_attribute("href") or ""
                            except Exception:
                                h = ""
                            if (t and target_substr.lower() in t.lower()) or (full_title.lower() in t.lower()):
                                match_href = h
                                break
                    except Exception:
                        continue
    except Exception:
        pass

    # If no link found on the current page, return 'No'
    if not match_href:
        print("No")
        return "No"

    # 4) Navigate to the matched article URL using goto (use relative URLs unchanged)
    try:
        await page.goto(match_href)
    except Exception:
        # If navigation fails, we cannot inspect the article; return No
        print("No")
        return "No"

    # Wait for main region to appear on the article page
    try:
        await page.get_by_role("main").wait_for(timeout=5000)
    except Exception:
        await asyncio.sleep(1)

    # 5) Inspect images for 'Shenzhou-20' related text in alt/src; fallback to figcaptions
    found = False
    try:
        # Try to search images inside the article's main region first
        imgs = page.get_by_role("main").get_by_role("img")
        if await imgs.count() == 0:
            imgs = page.get_by_role("img")
        ic = await imgs.count()
        for i in range(ic):
            img = imgs.nth(i)
            try:
                alt = (await img.get_attribute("alt") or "").lower()
            except Exception:
                alt = ""
            try:
                src = (await img.get_attribute("src") or "").lower()
            except Exception:
                src = ""
            combined = f"{alt} {src}"
            if re.search(r"shenzhou\s*-?\s*20|shenzhou20|shenzhou", combined, re.IGNORECASE):
                found = True
                break
    except Exception:
        found = False

    # Additional fallback: check figcaption text in the DOM
    if not found:
        try:
            fig_texts = await page.evaluate("Array.from(document.getElementsByTagName('figcaption')).map(e => e.innerText).join('\n')")
            if fig_texts and re.search(r"shenzhou\s*-?\s*20|shenzhou", fig_texts, re.IGNORECASE):
                found = True
        except Exception:
            pass

    result = "Yes" if found else "No"
    print(result)
    return result

